<?php
declare(strict_types=1);
session_start(); require_once dirname(__DIR__) . '/api/config.php';
if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}
$orders=db()->query('SELECT id,order_code,customer_name,customer_email,total,payment_status,order_status,payment_method,receipt_path,created_at FROM orders ORDER BY created_at DESC')->fetchAll();
function ordersEscape(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}
function ordersStatus(string $s):array{return match($s){'processing'=>['approved','Processing'],'shipped'=>['approved','Shipped'],'completed'=>['approved','Completed'],'payment_review'=>['pending','Payment review'],'cancelled'=>['cancelled','Cancelled'],default=>['awaiting','Pending payment']};}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Orders - Electra admin</title><link rel="stylesheet" href="admin.css"><style>.order-actions{display:flex;flex-wrap:wrap;gap:7px;align-items:center}.order-actions a,.order-actions button,.order-actions select{padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:#fff;color:var(--ink);font:700 11px inherit;text-decoration:none;cursor:pointer}.order-actions button{background:#11100e;color:#e6cd93;border-color:#11100e}.order-actions .danger{background:#fff7f6;color:#a33b30;border-color:#e3b9b3}.status-form{display:flex;gap:5px}.status-form select{max-width:125px}</style></head><body><div class="admin-shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark">E</span><span>Electra</span></a><p class="nav-label">Store management</p><nav class="side-nav"><a href="index.php"><span>Overview</span></a><a href="products.php"><span>Products</span></a><a class="active" href="orders.php"><span>Orders</span></a><a href="payments.php"><span>Payments</span></a></nav><p class="nav-label bottom-label">General</p><nav class="side-nav"><a href="index.php?view=settings"><span>Settings</span></a><a class="sign-out" href="logout.php"><span>Sign out</span></a></nav><div class="sidebar-foot"><i></i> Store online</div></aside><main class="workspace"><header class="workspace-header"><div><p class="kicker">Electra store</p><h1>Orders</h1></div><div class="profile"><span class="avatar"><?=ordersEscape(strtoupper(substr((string)$_SESSION['admin_name'],0,1)))?></span><span><strong><?=ordersEscape((string)$_SESSION['admin_name'])?></strong><small>Store manager</small></span></div></header><section class="page-heading"><div><p class="section-kicker">Transactions</p><h2>Order activity</h2><p>View details, receipts, approval, and delivery status.</p></div><span class="select-pill"><?=count($orders)?> orders</span></section><section class="card table-card"><div class="table-wrap"><table><thead><tr><th>Order</th><th>Customer</th><th>Date</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($orders as $order): $workflow=(string)($order['order_status']?:'pending_payment');[$style,$label]=ordersStatus($workflow); ?><tr><td><strong><?=ordersEscape((string)$order['order_code'])?></strong><small><?=ordersEscape((string)($order['payment_method']?:'No method'))?></small></td><td><strong><?=ordersEscape((string)$order['customer_name'])?></strong><small><?=ordersEscape((string)$order['customer_email'])?></small></td><td><?=date('M j, Y g:i a',strtotime((string)$order['created_at']))?></td><td><strong>₦<?=number_format((float)$order['total'],2)?></strong></td><td><span class="status <?=$style?>"><?=ordersEscape($label)?></span></td><td><div class="order-actions"><a href="order.php?id=<?=(int)$order['id']?>">View details</a><?php if(!empty($order['receipt_path'])):?><a href="../<?=ordersEscape((string)$order['receipt_path'])?>" target="_blank" rel="noopener">View receipt</a><?php endif;?><?php if($order['payment_status']!=='payment_approved'): ?><form method="post" action="order-actions.php"><input type="hidden" name="action" value="approve"><input type="hidden" name="order_id" value="<?=(int)$order['id']?>"><button type="submit">Approve</button></form><?php endif;?><form class="status-form" method="post" action="order-actions.php"><input type="hidden" name="action" value="status"><input type="hidden" name="order_id" value="<?=(int)$order['id']?>"><select name="status" aria-label="Change order status"><option value="pending_payment" <?=$workflow==='pending_payment'?'selected':''?>>Pending payment</option><option value="payment_review" <?=$workflow==='payment_review'?'selected':''?>>Payment review</option><option value="processing" <?=$workflow==='processing'?'selected':''?>>Processing</option><option value="shipped" <?=$workflow==='shipped'?'selected':''?>>Shipped</option><option value="completed" <?=$workflow==='completed'?'selected':''?>>Completed</option><option value="cancelled" <?=$workflow==='cancelled'?'selected':''?>>Cancelled</option></select><button type="submit">Update</button></form><form method="post" action="order-actions.php" onsubmit="return confirm('Delete this order permanently?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="order_id" value="<?=(int)$order['id']?>"><button class="danger" type="submit">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table><?php if(!$orders):?><div class="empty-state"><strong>No orders yet.</strong><p>Orders will appear here after checkout.</p></div><?php endif;?></div></section></main></div></body></html>
